-- Agata Nord color scheme: Dark or Light according to 'background', which Neovim sets from the
-- terminal background at start-up. Generated by tools/gen-app-themes.py from extras/palette.json.

local variant = vim.o.background == "light" and "light" or "dark"
vim.cmd.runtime("colors/agata-nord-" .. variant .. ".lua")
vim.g.colors_name = "agata-nord"
